{"tool": "submit_job", "args": {"source": "import fs from 'node:fs';
import vm from 'node:vm';

export async function gate({ referenceDir, submissionDir }) {
  try {
    const path = submissionDir + '/answer.mjs';
    let src;
    try {
      src = fs.readFileSync(path, 'utf8');
    } catch (e) {
      return { accept: false, reason: 'cannot read answer.mjs: ' + String(e && e.message) };
    }

    const transformed = src
      .replace(/export\s+default\s+/g, '')
      .replace(/export\s+/g, '')
      + '\n;(function(){ try { if (typeof dedupeSorted !== "undefined") { globalThis.dedupeSorted = dedupeSorted; } } catch (e) {} })();';

    const sandbox = {};
    vm.createContext(sandbox);

    try {
      new vm.Script(transformed, { filename: 'answer.mjs' }).runInContext(sandbox, { timeout: 2000 });
    } catch (e) {
      return { accept: false, reason: 'submission threw or timed out while loading: ' + String(e && e.message) };
    }

    if (typeof sandbox.dedupeSorted !== 'function') {
      return { accept: false, reason: 'no dedupeSorted function found after loading submission' };
    }

    // Build the call's input array as a literal INSIDE the vm script (so it is
    // created natively in the submission's own realm, avoiding cross-realm
    // instanceof/prototype mismatches) while hand-serializing numbers so -0,
    // NaN and Infinity survive -- JSON.stringify would silently turn -0 into
    // "0", destroying exactly the kind of edge case a naive implementation can
    // get wrong (Set-based dedup normalizes -0 to +0; a submission that keeps
    // the original sign instead would be wrong per the true oracle).
    function numLiteral(n) {
      if (Object.is(n, -0)) return '-0';
      if (Number.isNaN(n)) return 'NaN';
      if (n === Infinity) return 'Infinity';
      if (n === -Infinity) return '-Infinity';
      return String(n);
    }
    function arrLiteral(arr) {
      return '[' + arr.map(numLiteral).join(',') + ']';
    }

    function runInSandbox(code) {
      new vm.Script(code, { filename: 'probe.js' }).runInContext(sandbox, { timeout: 1000 });
    }

    // Results are extracted ELEMENT-BY-ELEMENT via property reads, never via
    // JSON (which also collapses -0/+0 and maps NaN/Infinity to null) and
    // never by comparing the returned array object directly with
    // assert.deepStrictEqual (which fails on constructor identity alone
    // across the vm realm boundary, independent of actual contents). Numbers
    // read out this way are primitives -- primitives have no realm identity,
    // so Object.is comparison against a host-computed expected value is
    // exact and matches what the true oracle (assert.deepStrictEqual, which
    // itself uses Object.is semantics for primitives) would decide.
    function callDedupe(inputArr) {
      runInSandbox(
        'globalThis.__ok = true; globalThis.__err = null; globalThis.__result = undefined;' +
        'try { globalThis.__result = dedupeSorted(' + arrLiteral(inputArr) + '); } ' +
        'catch (e) { globalThis.__ok = false; globalThis.__err = String(e && e.message); }'
      );
      if (!sandbox.__ok) throw new Error(sandbox.__err || 'submission threw');
      runInSandbox('globalThis.__isArr = Array.isArray(globalThis.__result); globalThis.__len = globalThis.__isArr ? globalThis.__result.length : -1;');
      if (!sandbox.__isArr) throw new Error('submission did not return an array (typeof ' + typeof sandbox.__result + ')');
      const len = sandbox.__len;
      const out = [];
      for (let i = 0; i < len; i++) {
        runInSandbox('globalThis.__elem = globalThis.__result[' + i + '];');
        out.push(sandbox.__elem);
      }
      return out;
    }

    function arraysMatch(actual, expected) {
      if (!Array.isArray(actual) || actual.length !== expected.length) return false;
      for (let i = 0; i < expected.length; i++) {
        if (!Object.is(actual[i], expected[i])) return false;
      }
      return true;
    }

    const failures = [];
    let ran = 0;

    function check(name, inputArr, expected) {
      ran++;
      try {
        const actual = callDedupe(inputArr);
        if (!arraysMatch(actual, expected)) {
          failures.push(name + ': expected ' + JSON.stringify(expected) + ' got ' + JSON.stringify(actual));
        }
      } catch (e) {
        failures.push(name + ': ' + String(e && e.message));
      }
    }

    // --- pinned fixed cases (operator-authored, reproduced exactly) ---
    check('empty array', [], []);
    check('single element', [5], [5]);
    check('no duplicates', [1, 2, 3], [1, 2, 3]);
    check('all duplicates', [4, 4, 4, 4], [4]);
    check('duplicates at the start', [1, 1, 2, 3], [1, 2, 3]);
    check('duplicates at the end', [1, 2, 3, 3], [1, 2, 3]);
    check('negative numbers with duplicates', [-3, -3, -1, 0, 0, 2], [-3, -1, 0, 2]);

    // --- pinned randomized property check, run exactly as specified ---
    const PINNED_TRIALS = 20;
    for (let trial = 0; trial < PINNED_TRIALS; trial++) {
      const len = 1 + Math.floor(Math.random() * 10);
      const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);
      const expected = [...new Set(arr)];
      check('pinned randomized trial ' + trial, arr, expected);
    }

    // --- wider coverage: bigger arrays, a much wider value range, and
    // lengths starting at 0, so a submission that only special-cases the
    // narrow range the pinned suite happens to sample cannot pass by
    // coincidence. Expected is computed the same way as the pinned oracle
    // (via Set), so normalization (e.g. of -0) is always decided the
    // identical way the true oracle decides it. ---
    const WIDE_TRIALS = 30;
    for (let trial = 0; trial < WIDE_TRIALS; trial++) {
      const len = Math.floor(Math.random() * 20);
      const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 4001) - 2000).sort((a, b) => a - b);
      const expected = [...new Set(arr)];
      check('wide randomized trial ' + trial, arr, expected);
    }

    // --- explicit edge cases a narrow-range sampler is unlikely to ever hit
    // by chance, but that a submission special-cased only to the pinned
    // suite's own literal shapes would fail. ---
    check('all duplicates of zero', [0, 0, 0, 0], [0]);
    check('zero among negatives and positives', [-1, -1, 0, 0, 0, 1], [-1, 0, 1]);
    check('large magnitude duplicates', [1000000000, 1000000000, 1000000001], [1000000000, 1000000001]);
    check('negative zero collapses with positive zero (matches Set-based oracle)', [-0, 0], [0]);
    check('all negative-zero duplicates', [-0, -0, -0], [0]);
    check('long run of a single value then another', [2, 2, 2, 2, 2, 2, 2, 2, 3], [2, 3]);
    check('two singleton runs', [-5, 7], [-5, 7]);

    const expectedCount = 7 + PINNED_TRIALS + WIDE_TRIALS + 7;
    if (ran !== expectedCount) {
      return { accept: false, reason: 'gate could not establish that the full suite ran: completed ' + ran + '/' + expectedCount + ' cases' };
    }

    if (failures.length > 0) {
      return { accept: false, reason: 'failed ' + failures.length + '/' + expectedCount + ' cases: ' + failures.slice(0, 5).join(' | ') };
    }

    return {
      accept: true,
      reason: 'all ' + expectedCount + ' cases passed (7 pinned fixed + ' + PINNED_TRIALS + ' pinned randomized + ' + WIDE_TRIALS + ' wide randomized + 7 explicit edge cases), executed in an isolated vm context; inputs are embedded as hand-serialized literals (preserving -0/NaN/Infinity, which JSON would destroy) and outputs extracted element-by-element as host primitives (never via JSON, never via cross-realm array identity) then compared with Object.is -- the same semantics assert.deepStrictEqual itself uses -- so the submission could neither exit early, hang, nor forge the result, and could not pass by exploiting sign-of-zero normalization or a narrow sampled range'
    };
  } catch (e) {
    return { accept: false, reason: 'gate internal error: ' + String(e && e.message) };
  }
}
"}, "rationale": "Hardened v2 against the live defeat: results are now extracted element-by-element and compared with Object.is instead of JSON (which was silently normalizing -0 to +0 and thereby accepting a submission the real oracle, using assert.deepStrictEqual's Object.is semantics, would reject), and coverage was widened with explicit zero/negative-zero/large-magnitude edge cases plus 30 wider-range randomized trials so a submission can't pass merely by fitting the pinned suite's narrow sampled range."}
